import { ETIQUETA_TIPO, formatoFechaLarga, formatoPesos, sentidoMovimiento } from "../utils/formato";
import { IconoMovimiento } from "./IconoMovimiento";

const SIGNO = { credito: "+ ", debito: "− ", apartado: "", neutro: "" };

const diaClave = (fecha) => new Date(fecha).toDateString();
const hoy = () => new Date().toDateString();
const ayer = () => new Date(Date.now() - 86400000).toDateString();
const etiquetaDia = (fecha) => {
  const clave = diaClave(fecha);
  if (clave === hoy()) return "Hoy";
  if (clave === ayer()) return "Ayer";
  return new Intl.DateTimeFormat("es-CO", { weekday: "long", day: "numeric", month: "long" }).format(new Date(fecha));
};
const hora = new Intl.DateTimeFormat("es-CO", { hour: "2-digit", minute: "2-digit" });

/**
 * Movimientos agrupados por día, con ícono por tipo, concepto
 * con línea punteada y monto con signo. `cuentaId` (o `_cuenta` por fila)
 * define el signo desde el punto de vista de una cuenta.
 */
export function Extracto({ transacciones, cuentaId, nombresBolsillo = {} }) {
  const grupos = [];
  for (const t of transacciones) {
    const clave = diaClave(t.fecha);
    const grupo = grupos.at(-1);
    if (grupo && grupo.clave === clave) grupo.filas.push(t);
    else grupos.push({ clave, etiqueta: etiquetaDia(t.fecha), filas: [t] });
  }

  return (
    <div className="extracto">
      {grupos.map((grupo) => (
        <section key={grupo.clave} className="extracto__dia" aria-label={grupo.etiqueta}>
          <h3 className="extracto__fecha-dia">{grupo.etiqueta}</h3>
          <ol>
            {grupo.filas.map((t) => {
              const referencia = cuentaId ?? t._cuenta;
              const sentido = referencia ? sentidoMovimiento(t, referencia) : "neutro";
              const bolsillo = t.bolsilloId ? nombresBolsillo[t.bolsilloId] : null;
              const detalle = [
                bolsillo ? `«${bolsillo}»` : null,
                t.tipo === "transferencia" && referencia
                  ? sentido === "debito"
                    ? `a cuenta #${t.cuentaDestinoId}`
                    : `desde cuenta #${t.cuentaOrigenId}`
                  : null,
                t.descripcion,
              ]
                .filter(Boolean)
                .join(" · ");
              return (
                <li key={`${t.id}-${referencia ?? ""}`} className="extracto__fila">
                  <IconoMovimiento tipo={t.tipo} sentido={sentido} />
                  <span className="extracto__concepto">
                    <strong>{ETIQUETA_TIPO[t.tipo] || t.tipo}</strong>
                    <span>
                      <time dateTime={t.fecha} title={formatoFechaLarga(t.fecha)}>
                        {hora.format(new Date(t.fecha))}
                      </time>
                      {detalle ? ` · ${detalle}` : ""}
                    </span>
                  </span>
                  <span className={`extracto__monto num ${sentido}`}>
                    {SIGNO[sentido]}
                    {formatoPesos(t.monto)}
                  </span>
                </li>
              );
            })}
          </ol>
        </section>
      ))}
    </div>
  );
}

import { useId, useState } from "react";
import { apartar, depositar, devolver, retirar, transferir } from "../services/recursos.service";
import { formatoPesos } from "../utils/formato";
import { AvisoError, Campo } from "./Formulario";

const MAXIMO_TRANSACCION = 2000000; // Regla 5 del negocio (CHECK en BD)

const TEXTOS = {
  retiro: { boton: "Retirar", exito: "Retiro registrado" },
  transferencia: { boton: "Transferir", exito: "Transferencia registrada" },
  deposito: { boton: "Depositar", exito: "Depósito registrado" },
  apartar: { boton: "Apartar", exito: "Dinero apartado" },
  devolver: { boton: "Devolver a la cuenta", exito: "Dinero devuelto a la cuenta" },
};

const RAPIDOS = [20000, 50000, 100000, 200000];

/**
 * Un solo formulario para los cinco movimientos. El backend valida montos,
 * propiedad y saldo disponible; aquí se guía y se muestra el efecto antes de
 * confirmar.
 */
export function FormularioMovimiento({
  tipo,
  cuenta,
  bolsillo: bolsilloInicial,
  bolsillos = [],
  disponible,
  otrasCuentas = [],
  alTerminar,
}) {
  const idMonto = useId();
  const idAyudaMonto = useId();
  const [monto, setMonto] = useState("");
  const [descripcion, setDescripcion] = useState("");
  const [bolsilloId, setBolsilloId] = useState(bolsilloInicial ? String(bolsilloInicial.id) : bolsillos[0] ? String(bolsillos[0].id) : "");
  const [destino, setDestino] = useState(otrasCuentas[0]?.id ? String(otrasCuentas[0].id) : "otra");
  const [destinoManual, setDestinoManual] = useState("");
  const [enviando, setEnviando] = useState(false);
  const [error, setError] = useState(null);

  const bolsillo = bolsilloInicial || bolsillos.find((b) => String(b.id) === bolsilloId);
  const libre = Number(disponible ?? 0);
  const tope =
    tipo === "devolver"
      ? Number(bolsillo?.saldo ?? 0)
      : tipo === "deposito"
        ? MAXIMO_TRANSACCION
        : Math.min(libre, MAXIMO_TRANSACCION);

  const valor = Number(monto);
  const valido = Number.isFinite(valor) && valor > 0 && valor <= tope;
  const excedido = Number.isFinite(valor) && valor > tope;

  // Efecto sobre el disponible: apartar, retirar y transferir lo reducen.
  const despues =
    tipo === "deposito" || tipo === "devolver" ? libre + (valor || 0) : libre - (valor || 0);

  const enviar = async (evento) => {
    evento.preventDefault();
    if (!valido) return;
    setEnviando(true);
    setError(null);
    const base = { monto: valor };
    if (descripcion.trim()) base.descripcion = descripcion.trim();
    try {
      if (tipo === "retiro") await retirar({ ...base, cuentaOrigenId: cuenta.id });
      if (tipo === "deposito") await depositar({ ...base, cuentaDestinoId: cuenta.id });
      if (tipo === "transferencia") {
        const cuentaDestinoId = Number(destino === "otra" ? destinoManual : destino);
        await transferir({ ...base, cuentaOrigenId: cuenta.id, cuentaDestinoId });
      }
      if (tipo === "apartar") await apartar(bolsillo.id, base);
      if (tipo === "devolver") await devolver(bolsillo.id, base);
      alTerminar(TEXTOS[tipo].exito, `${formatoPesos(valor)}${bolsillo ? ` · ${bolsillo.nombre}` : ""}`);
    } catch (fallo) {
      setError(fallo);
      setEnviando(false);
    }
  };

  const rapidos = RAPIDOS.filter((r) => r <= tope);

  return (
    <form className="formulario" onSubmit={enviar}>
      {tipo === "apartar" && !bolsilloInicial ? (
        <Campo etiqueta="Bolsillo">
          {(props) => (
            <select {...props} className="selector" value={bolsilloId} onChange={(e) => setBolsilloId(e.target.value)} required>
              {bolsillos.map((b) => (
                <option key={b.id} value={b.id}>
                  {b.nombre} · {formatoPesos(b.saldo)}
                </option>
              ))}
            </select>
          )}
        </Campo>
      ) : null}

      {tipo === "transferencia" ? (
        <>
          <Campo etiqueta="Para">
            {(props) => (
              <select {...props} className="selector" value={destino} onChange={(e) => setDestino(e.target.value)}>
                {otrasCuentas.map((otra) => (
                  <option key={otra.id} value={otra.id}>
                    Mi cuenta {otra.numeroCuenta}
                  </option>
                ))}
                <option value="otra">Otra cuenta (por ID)</option>
              </select>
            )}
          </Campo>
          {destino === "otra" ? (
            <Campo etiqueta="ID de la cuenta destino" ayuda="Pídale el número interno de cuenta al destinatario.">
              {(props) => (
                <input
                  {...props}
                  className="entrada num"
                  type="number"
                  min="1"
                  step="1"
                  inputMode="numeric"
                  required
                  value={destinoManual}
                  onChange={(e) => setDestinoManual(e.target.value)}
                />
              )}
            </Campo>
          ) : null}
        </>
      ) : null}

      <div className="monto">
        <label htmlFor={idMonto} className="monto__etiqueta">
          ¿Cuánto?
        </label>
        <div className="monto__caja">
          <span aria-hidden="true">$</span>
          <input
            id={idMonto}
            className="monto__entrada cifra"
            type="number"
            inputMode="numeric"
            min="1"
            step="1"
            placeholder="0"
            required
            autoFocus
            aria-describedby={idAyudaMonto}
            aria-invalid={excedido ? "true" : undefined}
            value={monto}
            onChange={(e) => setMonto(e.target.value)}
          />
        </div>
        <p id={idAyudaMonto} className={`monto__ayuda ${excedido ? "debito" : "texto-3"}`}>
          {excedido
            ? `Máximo ${formatoPesos(tope)} para esta operación.`
            : tipo === "deposito"
              ? `Hasta ${formatoPesos(MAXIMO_TRANSACCION)} por movimiento.`
              : tipo === "devolver"
                ? `El bolsillo tiene ${formatoPesos(tope)}.`
                : `Disponible: ${formatoPesos(libre)}.`}
        </p>
        {rapidos.length || tipo !== "deposito" ? (
          <div className="chips" role="group" aria-label="Montos rápidos">
            {rapidos.map((r) => (
              <button key={r} type="button" className="chip" onClick={() => setMonto(String(r))} aria-pressed={valor === r}>
                {formatoPesos(r)}
              </button>
            ))}
            {tipo !== "deposito" && tope > 0 ? (
              <button type="button" className="chip" onClick={() => setMonto(String(Math.floor(tope)))} aria-pressed={valor === Math.floor(tope)}>
                Todo
              </button>
            ) : null}
          </div>
        ) : null}
      </div>

      <Campo etiqueta="Descripción (opcional)">
        {(props) => (
          <input {...props} className="entrada" maxLength={120} value={descripcion} onChange={(e) => setDescripcion(e.target.value)} />
        )}
      </Campo>

      {valido && tipo !== "deposito" ? (
        <dl className="resumen-mov" aria-live="polite">
          <div>
            <dt>Disponible después</dt>
            <dd className="num">{formatoPesos(Math.max(despues, 0))}</dd>
          </div>
          {bolsillo && (tipo === "apartar" || tipo === "devolver") ? (
            <div>
              <dt>«{bolsillo.nombre}» quedará con</dt>
              <dd className="num apartado">
                {formatoPesos(Number(bolsillo.saldo) + (tipo === "apartar" ? valor : -valor))}
              </dd>
            </div>
          ) : null}
        </dl>
      ) : null}

      <AvisoError error={error} />

      <button className="boton boton--grande boton--ancho" type="submit" disabled={enviando || !valido}>
        {enviando ? "Procesando…" : valido ? `${TEXTOS[tipo].boton} ${formatoPesos(valor)}` : TEXTOS[tipo].boton}
      </button>
    </form>
  );
}

import { ArrowDownLeft, ArrowUpRight, ArrowsLeftRight, Coins, PiggyBank } from "@phosphor-icons/react";

// Un ícono por tipo de movimiento: se reconoce sin leer.
const ICONOS = {
  deposito: ArrowDownLeft,
  retiro: ArrowUpRight,
  transferencia: ArrowsLeftRight,
  apartado: PiggyBank,
  devolucion: Coins,
};

export function IconoMovimiento({ tipo, sentido = "neutro" }) {
  const Icono = ICONOS[tipo] || ArrowsLeftRight;
  return (
    <span className={`icono-mov icono-mov--${sentido}`} aria-hidden="true">
      <Icono size={18} weight="bold" />
    </span>
  );
}

import { Desktop, Moon, Sun } from "@phosphor-icons/react";
import { useTema } from "../hooks/useTema";
import { rotarTema } from "../utils/tema";

const TEXTO = { sistema: "Tema del sistema", claro: "Tema claro", oscuro: "Tema oscuro" };
const ICONO = { sistema: Desktop, claro: Sun, oscuro: Moon };

export function SelectorTema({ conTexto = false }) {
  const tema = useTema();
  const Icono = ICONO[tema] || Desktop;
  return (
    <button
      type="button"
      className={`boton boton--fantasma ${conTexto ? "" : "boton--icono"}`}
      onClick={rotarTema}
      aria-label={`${TEXTO[tema]}. Cambiar tema`}
      title={`${TEXTO[tema]} (clic para cambiar)`}
    >
      <Icono size={18} weight="regular" aria-hidden="true" />
      {conTexto ? <span>{TEXTO[tema]}</span> : null}
    </button>
  );
}

// Preferencia de tema por visitante, compartida entre el selector y el Toaster.
export const CLAVE_TEMA = "bolsillo.tema";
const SIGUIENTE = { sistema: "claro", claro: "oscuro", oscuro: "sistema" };
const suscriptores = new Set();

export const leerTema = () => {
  try {
    return localStorage.getItem(CLAVE_TEMA) || "sistema";
  } catch {
    return "sistema";
  }
};

let actual = leerTema();

export const aplicarTema = (tema) => {
  const raiz = document.documentElement;
  if (tema === "claro") raiz.dataset.theme = "light";
  else if (tema === "oscuro") raiz.dataset.theme = "dark";
  else delete raiz.dataset.theme;
};

export const temaInicial = () => aplicarTema(actual);

export const obtenerTema = () => actual;

export const suscribirTema = (fn) => {
  suscriptores.add(fn);
  return () => suscriptores.delete(fn);
};

export const rotarTema = () => {
  actual = SIGUIENTE[actual] || "sistema";
  aplicarTema(actual);
  try {
    localStorage.setItem(CLAVE_TEMA, actual);
  } catch {
    // Sin almacenamiento: dura hasta recargar.
  }
  suscriptores.forEach((fn) => fn());
};

// Para Sonner: "system" sigue al sistema operativo.
export const temaParaToaster = (tema) => (tema === "claro" ? "light" : tema === "oscuro" ? "dark" : "system");
